    std::vector<std::string> tokens;
    for (std::string word; input >> word;) tokens.push_back(word);
    assert(tokens.size() == 3 && tokens[1] == "|");
    std::cout << "left=" << tokens[0] << " right=" << tokens[2] << '\n';
}

